"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[510],{6510:(e,t,i)=>{i.d(t,{LanguageProvider:()=>r,o:()=>l});var s=i(5155),a=i(2115);let o={en:{topbar:{home:"Home",about:"About me",projects:"Projects",skills:"Skills",toggleLabel:"Change language",langShort:"EN"},hero:{tags:["Full-stack","AI","Software"],subtitle:"Building reliable systems and web applications, solving problems and learning new technologies."},ctas:{download:"Download CV",about:"About Me",projects:"See my projects"},home:{featured:{title:"Featured projects",subtitle:"Web, cybersecurity, games: a glimpse of what I build.",seeAll:"See all projects",items:[{title:"Oziris Optique",tag:"Web \xb7 Next.js",desc:"Full redesign of an optician's website with a custom Payload CMS back office, deployed with Docker.",image:"/photos/Oziris/Home.png"},{title:"Forensic",tag:"Cybersecurity",desc:"Disk image and network trace analysis, up to the full investigation report.",image:"/photos/Forensic/Attack_summary.png"},{title:"RType",tag:"Game \xb7 C++",desc:"Multiplayer shooter with lobbies and lag compensation for a smooth online experience.",image:"/photos/Rtype/Gameplay.png"}]},explore:{title:"Dig deeper",items:[{href:"/about/",title:"My journey",desc:"From AI at Enedis to full-stack at SAS Digital Box: my background, experiences and internship reports.",cta:"Read my story"},{href:"/skills/",title:"My toolbox",desc:"12 domains, from offensive security to frontend: every technology I work with.",cta:"Browse my skills"},{href:"/projects/",title:"My projects",desc:"7 projects with screenshots, context and stack: web apps, pentests, games.",cta:"Explore projects"}]},contact:{title:"Have a project or an opportunity?",subtitle:"Internship, job, collaboration or a simple question: my inbox is always open.",email:"Send me an email"}},stats:[{value:"110+",label:"GitHub Projects",icon:"/icons/github.svg"},{value:"1400+",label:"Commits",icon:"/icons/commit.svg"},{value:"24 / 7",label:"Available via Email",icon:"/icons/email.svg"}],about:{title:"About Me",paragraphs:["My name is Nicolas Audibert, and I am a 5th-year engineering student in the Programme Grande \xc9cole at EPITECH Marseille, a project-based generalist curriculum covering software development, systems, and networks. In my 4th year, I complemented it with a dual degree in cybersecurity at EPITECH Brussels.","My internships let me work on real-world projects: AI development at Enedis (object detection on aerial images, semantic node generation to complete incomplete graphs), then full-stack development at SAS Digital Box and La Bo\xeete Immo with React, Next.js, PHP, and TypeScript, including deployment, production maintenance, and technical documentation.","On the cybersecurity side, in partnership with Expleo, I investigated a network compromise and audited the security of a WPA2 Wi-Fi network, up to writing the incident and audit reports. I keep practicing on my homelab (Proxmox server, Kali Linux VM, Docker containers, self-hosted WireGuard VPN) and on TryHackMe, where I rank in the top 5%. I also placed 26th out of 400 in EPITECH's Burp CTF.","Passionate about computers since childhood, I discovered them at the age of 3 and started coding in middle school. Outside of tech, I practice airsoft and boxing, which build rigor, strategy, and team spirit, and I enjoy drones, photography, video, and music (drums and piano).","Used to working both in teams and independently, I adapt quickly to new environments. I speak English (B2, TOEIC 865) and Italian (B1), and I constantly seek to deepen my skills and take on new technical challenges."],seeMore:"See more",seeLess:"See less"},experience:{title:"Experiences",items:[{title:"AI Developer — Enedis (Internship)",date:"Mar 2025 - Jul 2025 \xb7 Marseille \xb7 On-site",desc:"Aerial object detection. Semantic generation of graph nodes.",skills:"Skills: Artificial Intelligence (AI), Python",file:"/files/Stage_Enedis_Nicolas_Audibert.pdf"},{title:"Full Stack Developer — SAS Digital Box (Internship)",date:"Oct 2024 - Mar 2025 \xb7 Marseille \xb7 On-site",desc:"Created dashboards, integrated automated mailing, improved the existing site.",skills:"Skills: Next.js, Firebase, and more",file:"/files/Stage_NFT_Box_Collections_Nicolas_Audibert.pdf"},{title:"Full Stack Developer — La Bo\xeete Immo (Internship)",date:"Jul 2023 - Dec 2023 \xb7 Hy\xe8res \xb7 On-site",desc:"Resolved support tickets, delivered functional evolutions, optimized the user experience on Hektor.",skills:"Skills: PHP, Postman, MySQL, and more",file:"/files/Stage_La_Boite_Immo_Nicolas_Audibert.pdf"}]},footer:{contact:"Contact",social:"Social",navigation:"Navigation",home:"Home",about:"About",projects:"Projects",skills:"Skills",rights:"All rights reserved."},carousel:{itemLabel:"Item",reset:"Reset View",tooSmall:"TOO SMALL"},competences:{title:"Technologies Used"},skills:{title:"Skills",categories:[{title:"AI & Data",skills:["AI","LLM Integration","Python (NumPy/Pandas)","Data Visualization"]},{title:"Incident Response & Forensics",skills:["Volatility","Autopsy","Wireshark","VirusTotal","Log Analysis","Incident Reports"]},{title:"Offensive Security",skills:["Burp Suite","Nmap","Kali Linux","Metasploit","OWASP ZAP","aircrack-ng","hashcat","pwntools"]},{title:"Frontend",skills:["React.js","Next.js","TypeScript","JavaScript","Tailwind CSS","Material-UI"]},{title:"Backend & APIs",skills:["Express.js","Node.js","Payload CMS","REST APIs","GraphQL","Postman"]},{title:"Cloud & Hosting",skills:["AWS Security Basics","Firebase","Vercel","Railway","CI/CD"]},{title:"Systems & Infrastructure",skills:["Linux","Windows","Proxmox","Docker","WireGuard"]},{title:"Languages",skills:["Python","TypeScript","JavaScript","C","C++","PHP"]},{title:"Databases",skills:["SQL","PostgreSQL","SQLite","Firestore","MongoDB"]},{title:"Tools & IDEs",skills:["Git","GitHub","VS Code","Postman"]},{title:"Methods",skills:["Agile (Scrum)","TMA","Technical Documentation"]},{title:"Productivity",skills:["Microsoft Office","Notion","Trello","GitHub Projects"]}]},projects:{title:"My Projects",area:{title:"Area",paragraphs:["AREA (Application for Remote Execution of Actions) is a project developed as part of the Epitech curriculum. It is a web and mobile application that automates tasks by connecting different services together.","Inspired by platforms like IFTTT (If This Then That) and Zapier, AREA lets users create actions that trigger in response to specific events, from both a web browser and a mobile app."]},cryptobottle:{title:"Cryptobottle",paragraphs:["Cryptobottle is a web platform that combines the wine world and blockchain. Users can create, buy, and collect virtual bottles containing cryptocurrencies and real-world benefits (promotions, offers, discounts). The project blends investment, digital art, and a marketplace.","I developed a configurable dynamic pop-up system and a complete admin dashboard, and I contributed to the overall design and styling of the application."]},forensic:{title:"Forensic",paragraphs:["During my fourth year, I completed a dual degree in cybersecurity at Epitech Brussels, supervised by industry professionals. This program let me deepen my knowledge of Online/Local Pentesting, Forensics, Threat Hunting, Risk Analysis, and Architecture & Cloud Security.","As part of this program, I carried out a forensic project that involved analyzing a disk image and a provided network trace, extracting relevant data, and writing a report detailing the investigation's conclusions."]},myHunter:{title:"MyHunter",paragraphs:["MyHunter is a cops-and-robbers game where the player acts as a police officer tasked with eliminating thieves while avoiding civilians. Gameplay is based on a shooting system that requires speed, accuracy, and timing, with penalties for mistakes.","The game features three types of characters: thieves, who score points when neutralized, and civilians, men or women, who must be avoided at all costs. Hitting a civilian results in a heavy point loss."]},pentest:{title:"Pentest",paragraphs:["During my Epitech studies, I completed several pentest projects on TryHackMe, complemented by self-directed cybersecurity training. These experiences strengthened my skills in vulnerability analysis, penetration testing, and technical report writing.","During my fourth year, I completed a dual degree in cybersecurity at Epitech Brussels, supervised by industry professionals. This program let me deepen my knowledge of Online/Local Pentesting, Forensics, Threat Hunting, Risk Analysis, and Architecture & Cloud Security."]},rtype:{title:"RType",paragraphs:["R-Type is a side-scrolling shooter where the player pilots a spaceship against waves of enemies. Gameplay relies on dodging, strategic weapon use, and the Force module, which is essential for offense and defense.","We developed a multiplayer version of R-Type, including match creation, lobbies to bring players together, and a lag-compensation system. These features enabled a smooth, synchronized experience even with varied network connections."]},oziris:{title:"Oziris Optique",paragraphs:["Oziris Optique is an independent optician in Marseille with two stores. I carried out the complete redesign of its website with Next.js and TypeScript, built around a self-hosted, customized Payload CMS back office: a dashboard organized by site page, autonomous management of news (drafts, scheduled publishing), staff, stores, and brands, and a contact request tracker with spam filtering.","The site is deployed with Docker on a VPS, behind a Caddy HTTPS reverse proxy, with a PostgreSQL database. It features a map with self-hosted tiles, a dark mode, SEO redirects from the old site, and attention to GDPR and WCAG 2.1 AA accessibility."]}}},fr:{topbar:{home:"Accueil",about:"\xc0 propos",projects:"Projets",skills:"Comp\xe9tences",toggleLabel:"Changer de langue",langShort:"FR"},hero:{tags:["Full-stack","IA","Logiciel"],subtitle:"Construire des syst\xe8mes fiables et des applications web, r\xe9soudre des probl\xe8mes et apprendre de nouvelles technologies."},ctas:{download:"T\xe9l\xe9charger le CV",about:"\xc0 propos",projects:"Voir mes projets"},home:{featured:{title:"Projets phares",subtitle:"Web, cybers\xe9curit\xe9, jeux : un aper\xe7u de ce que je construis.",seeAll:"Voir tous les projets",items:[{title:"Oziris Optique",tag:"Web \xb7 Next.js",desc:"Refonte compl\xe8te du site d'un opticien avec un back-office Payload CMS sur mesure, d\xe9ploy\xe9 avec Docker.",image:"/photos/Oziris/Home.png"},{title:"Forensic",tag:"Cybers\xe9curit\xe9",desc:"Analyse d'une image disque et d'une trame r\xe9seau, jusqu'au rapport d'enqu\xeate complet.",image:"/photos/Forensic/Attack_summary.png"},{title:"RType",tag:"Jeu \xb7 C++",desc:"Shooter multijoueur avec lobbies et lag compensation pour une exp\xe9rience en ligne fluide.",image:"/photos/Rtype/Gameplay.png"}]},explore:{title:"En savoir plus",items:[{href:"/about/",title:"Mon parcours",desc:"De l'IA chez Enedis au full-stack chez SAS Digital Box : mon parcours, mes exp\xe9riences et mes rapports de stage.",cta:"D\xe9couvrir mon parcours"},{href:"/skills/",title:"Ma bo\xeete \xe0 outils",desc:"12 domaines, de la s\xe9curit\xe9 offensive au frontend : toutes les technologies que j'utilise.",cta:"Voir mes comp\xe9tences"},{href:"/projects/",title:"Mes projets",desc:"7 projets avec captures, contexte et stack : applications web, pentests, jeux.",cta:"Explorer les projets"}]},contact:{title:"Un projet ou une opportunit\xe9 ?",subtitle:"Stage, emploi, collaboration ou simple question : ma bo\xeete mail est toujours ouverte.",email:"M'envoyer un email"}},stats:[{value:"110+",label:"Projets GitHub",icon:"/icons/github.svg"},{value:"1400+",label:"Commits",icon:"/icons/commit.svg"},{value:"24 / 7",label:"Disponible par email",icon:"/icons/email.svg"}],about:{title:"\xc0 propos de moi",paragraphs:["Je m'appelle Nicolas Audibert, \xe9tudiant ing\xe9nieur en 5ᵉ ann\xe9e du Programme Grande \xc9cole \xe0 EPITECH Marseille, un cursus g\xe9n\xe9raliste par projets sur les th\xe8mes du d\xe9veloppement, des syst\xe8mes et des r\xe9seaux. En 4ᵉ ann\xe9e, je l'ai compl\xe9t\xe9 par un double dipl\xf4me en cybers\xe9curit\xe9 \xe0 EPITECH Bruxelles.","Mes stages m'ont permis de travailler sur des projets concrets : d\xe9veloppement IA chez Enedis (d\xe9tection d'objets sur images a\xe9riennes, g\xe9n\xe9ration s\xe9mantique de nœuds pour compl\xe9ter des graphes incomplets), puis d\xe9veloppement full stack chez SAS Digital Box et La Bo\xeete Immo en React, Next.js, PHP et TypeScript, avec d\xe9ploiement, maintenance en production et documentation technique.","C\xf4t\xe9 cybers\xe9curit\xe9, j'ai men\xe9 en partenariat avec Expleo l'investigation d'une compromission r\xe9seau et l'audit de s\xe9curit\xe9 d'un r\xe9seau Wi-Fi WPA2, jusqu'\xe0 la r\xe9daction des rapports d'incident et d'audit. Je continue \xe0 pratiquer sur mon homelab (serveur Proxmox, VM Kali Linux, conteneurs Docker, VPN WireGuard auto-h\xe9berg\xe9) et sur TryHackMe, o\xf9 je fais partie du top 5 %. J'ai \xe9galement termin\xe9 26ᵉ sur 400 au CTF Burp d'EPITECH.","Passionn\xe9 d'informatique depuis l'enfance, j'ai d\xe9couvert les ordinateurs d\xe8s l'\xe2ge de 3 ans, puis le code au coll\xe8ge. En dehors de l'informatique, je pratique l'airsoft et la boxe, qui d\xe9veloppent rigueur, strat\xe9gie et esprit d'\xe9quipe, et je m'int\xe9resse aux drones, \xe0 la photo, \xe0 la vid\xe9o et \xe0 la musique (batterie et piano).","Habitu\xe9 au travail en \xe9quipe comme en autonomie, je m'adapte rapidement \xe0 de nouveaux environnements. Je parle anglais (B2, TOEIC 865) et italien (B1), et je cherche constamment \xe0 approfondir mes comp\xe9tences et \xe0 relever de nouveaux d\xe9fis techniques."],seeMore:"Voir plus",seeLess:"Voir moins"},experience:{title:"Exp\xe9riences",items:[{title:"D\xe9veloppeur IA — Enedis (Stage)",date:"mars 2025 - juil. 2025 \xb7 Marseille \xb7 Sur site",desc:"D\xe9tection d'objets a\xe9riens. G\xe9n\xe9ration s\xe9mantique de nœuds de graphes.",skills:"Comp\xe9tences : Intelligence artificielle (IA), Python",file:"/files/Stage_Enedis_Nicolas_Audibert.pdf"},{title:"D\xe9veloppeur Full Stack — SAS Digital Box (Stage)",date:"oct. 2024 - mars 2025 \xb7 Marseille \xb7 Sur site",desc:"Cr\xe9ation de dashboards, int\xe9gration de mailing automatique, am\xe9liorations du site existant.",skills:"Comp\xe9tences : Next.js, Firebase, et plus",file:"/files/Stage_NFT_Box_Collections_Nicolas_Audibert.pdf"},{title:"D\xe9veloppeur Full Stack — La Bo\xeete Immo (Stage)",date:"juil. 2023 - d\xe9c. 2023 \xb7 Hy\xe8res \xb7 Sur site",desc:"R\xe9solution de tickets SAV, \xe9volutions fonctionnelles, optimisation de l'exp\xe9rience utilisateur sur Hektor.",skills:"Comp\xe9tences : PHP, Postman, MySQL, et plus",file:"/files/Stage_La_Boite_Immo_Nicolas_Audibert.pdf"}]},footer:{contact:"Contact",social:"R\xe9seaux",navigation:"Navigation",home:"Accueil",about:"\xc0 propos",projects:"Projets",skills:"Comp\xe9tences",rights:"Tous droits r\xe9serv\xe9s."},carousel:{itemLabel:"\xc9l\xe9ment",reset:"R\xe9initialiser la vue",tooSmall:"\xc9cran trop petit"},competences:{title:"Technologies utilis\xe9es"},skills:{title:"Comp\xe9tences",categories:[{title:"IA & Donn\xe9es",skills:["IA","Int\xe9gration LLM","Python (NumPy/Pandas)","Visualisation de donn\xe9es"]},{title:"Investigation & r\xe9ponse \xe0 incident",skills:["Volatility","Autopsy","Wireshark","VirusTotal","Analyse de logs","Rapports d'incident"]},{title:"S\xe9curit\xe9 offensive",skills:["Burp Suite","Nmap","Kali Linux","Metasploit","OWASP ZAP","aircrack-ng","hashcat","pwntools"]},{title:"Frontend",skills:["React.js","Next.js","TypeScript","JavaScript","Tailwind CSS","Material-UI"]},{title:"Backend & APIs",skills:["Express.js","Node.js","Payload CMS","API REST","GraphQL","Postman"]},{title:"Cloud & H\xe9bergement",skills:["Notions de s\xe9curit\xe9 AWS","Firebase","Vercel","Railway","CI/CD"]},{title:"Syst\xe8mes & infrastructure",skills:["Linux","Windows","Proxmox","Docker","WireGuard"]},{title:"Langages",skills:["Python","TypeScript","JavaScript","C","C++","PHP"]},{title:"Bases de donn\xe9es",skills:["SQL","PostgreSQL","SQLite","Firestore","MongoDB"]},{title:"Outils & IDEs",skills:["Git","GitHub","VS Code","Postman"]},{title:"M\xe9thodes",skills:["Agile (Scrum)","TMA","Documentation technique"]},{title:"Productivit\xe9",skills:["Microsoft Office","Notion","Trello","GitHub Projects"]}]},projects:{title:"Mes Projets",area:{title:"Area",paragraphs:["AREA (Application for Remote Execution of Actions) est un projet d\xe9velopp\xe9 dans le cadre du cursus Epitech. Il s'agit d'une application disponible en version web et mobile permettant d'automatiser des t\xe2ches en connectant diff\xe9rents services entre eux.","Inspir\xe9e par des plateformes comme IFTTT (If This Then That) et Zapier, AREA permet aux utilisateurs de cr\xe9er des actions qui se d\xe9clenchent en r\xe9ponse \xe0 des \xe9v\xe9nements sp\xe9cifiques, aussi bien depuis un navigateur web que depuis une application mobile."]},cryptobottle:{title:"Cryptobottle",paragraphs:["Cryptobottle est une plateforme web qui allie univers viticole et blockchain. Les utilisateurs peuvent cr\xe9er, acheter et collectionner des bouteilles virtuelles contenant des cryptomonnaies et des avantages r\xe9els (promotions, offres, remises). Le projet m\xeale investissement, art digital et marketplace.","J'y ai d\xe9velopp\xe9 un syst\xe8me de pop-up dynamique configurable ainsi qu'un dashboard d'administration complet, et particip\xe9 \xe0 la conception et au style global de l'application."]},forensic:{title:"Forensic",paragraphs:["Lors de ma quatri\xe8me ann\xe9e, j'ai suivi un double dipl\xf4me en cybers\xe9curit\xe9 \xe0 Epitech Bruxelles, encadr\xe9 par des professionnels du secteur. Cette formation m'a permis d'approfondir mes connaissances en Online/Local Pentesting, Forensics, Threat Hunting, Risk Analysis et Architecture & Cloud Security.","Dans le cadre de cette formation, j'ai r\xe9alis\xe9 un projet de forensic consistant \xe0 analyser une image disque ainsi qu'une trame r\xe9seau fournies, extraire des donn\xe9es pertinentes et r\xe9diger un rapport d\xe9taillant les conclusions de l'enqu\xeate."]},myHunter:{title:"MyHunter",paragraphs:["MyHunter est un jeu police/voleur dans lequel le joueur incarne un policier charg\xe9 d'\xe9liminer des voleurs tout en \xe9vitant les civils. Le gameplay repose sur un syst\xe8me de tir demandant rapidit\xe9, pr\xe9cision et respect du timing, avec des p\xe9nalit\xe9s appliqu\xe9es en cas d'erreur.","Le jeu met en sc\xe8ne trois types de personnages : les voleurs, qui rapportent des points lorsqu'ils sont neutralis\xe9s, et les civils, hommes ou femmes, qu'il faut \xe9viter \xe0 tout prix. Toucher un civil entra\xeene une lourde perte de points."]},pentest:{title:"Pentest",paragraphs:["Au cours de mon cursus \xe0 Epitech, j'ai r\xe9alis\xe9 plusieurs projets de pentest sur TryHackMe, compl\xe9t\xe9s par des entra\xeenements en cybers\xe9curit\xe9 effectu\xe9s en autonomie. Ces exp\xe9riences m'ont permis de renforcer mes comp\xe9tences en analyse de vuln\xe9rabilit\xe9s, tests d'intrusion et r\xe9daction de rapports techniques.","Lors de ma quatri\xe8me ann\xe9e, j'ai suivi un double dipl\xf4me en cybers\xe9curit\xe9 \xe0 Epitech Bruxelles, encadr\xe9 par des professionnels du secteur. Cette formation m'a permis d'approfondir mes connaissances en Online/Local Pentesting, Forensics, Threat Hunting, Risk Analysis et Architecture & Cloud Security."]},rtype:{title:"RType",paragraphs:["R-Type est un jeu de tir \xe0 d\xe9filement horizontal dans lequel le joueur pilote un vaisseau spatial affrontant des vagues d'ennemis. Le gameplay repose sur l'esquive, l'utilisation strat\xe9gique des armes et du module Force, essentiel pour attaquer et se d\xe9fendre.","Nous avons d\xe9velopp\xe9 une version multijoueur de R-Type, int\xe9grant la cr\xe9ation de parties, des lobbies pour r\xe9unir les joueurs et un syst\xe8me de lag compensation. Ces fonctionnalit\xe9s ont permis une exp\xe9rience fluide et synchronis\xe9e, m\xeame avec des connexions r\xe9seau vari\xe9es."]},oziris:{title:"Oziris Optique",paragraphs:["Oziris Optique est un opticien ind\xe9pendant marseillais dot\xe9 de deux boutiques. J'ai r\xe9alis\xe9 la refonte compl\xe8te de son site en Next.js et TypeScript, autour d'un back-office Payload CMS auto-h\xe9berg\xe9 et personnalis\xe9 : tableau de bord organis\xe9 par page du site, gestion autonome des actualit\xe9s (brouillons, publication programm\xe9e), de l'\xe9quipe, des boutiques et des marques, et suivi des demandes de contact avec filtrage anti-spam.","Le site est d\xe9ploy\xe9 avec Docker sur un VPS, derri\xe8re un reverse proxy HTTPS Caddy, avec une base PostgreSQL. Il int\xe8gre une carte aux tuiles auto-h\xe9berg\xe9es, un mode sombre, des redirections SEO depuis l'ancien site, ainsi qu'une attention port\xe9e au RGPD et \xe0 l'accessibilit\xe9 WCAG 2.1 AA."]}}}},n=(0,a.createContext)(null);function r(e){let{children:t}=e,[i,r]=(0,a.useState)("en");(0,a.useEffect)(()=>{let e=window.localStorage.getItem("lang");("en"===e||"fr"===e)&&r(e)},[]),(0,a.useEffect)(()=>{window.localStorage.setItem("lang",i)},[i]);let l=()=>r(e=>"en"===e?"fr":"en"),c=(0,a.useMemo)(()=>({language:i,copy:o[i],toggleLanguage:l,setLanguage:r}),[i]);return(0,s.jsx)(n.Provider,{value:c,children:t})}function l(){let e=(0,a.useContext)(n);if(!e)throw Error("useLanguage must be used within a LanguageProvider");return e}}}]);